// spec: .qa/e2e/specs/history.md (2.2) · case: .qa/tests/history/HIST-006.md
// seed: tests/seed.user.spec.ts (сессия user.json — из профиля Mac devA, без нового входа: лимит устройств 2/2)
// Только чтение: листает «היסטוריה» до конца, ничего не создаёт и не меняет. Даты и числа не зашиты — данные растут.
import { test, expect, type Page } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user.json') });

const DAY = /^(היום|אתמול|\d{1,2}\.\d{1,2}(\.\d{2,4})?)$/;
const ROW = /ניטור, /;
const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();

type Day = { day: string; count: number | null; countText: string; rows: number };

// Заголовок дня: строка [«07.10», «33 ניטורים»]; записи дня — в соседнем блоке той же секции.
async function readDays(page: Page): Promise<Day[]> {
  const heads = page.getByRole('heading', { name: DAY }).filter({ visible: true });
  const raw = await heads.evaluateAll((els) => els.map((h) => {
    const header = h.parentElement!;
    const section = header.parentElement!;
    const rows = [...section.querySelectorAll('[role="button"]')]
      .filter((b) => /ניטור, /.test(b.getAttribute('aria-label') ?? '')).length;
    const countText = [...header.children].filter((c) => c !== h).map((c) => (c as HTMLElement).innerText).join(' ');
    return { day: (h as HTMLElement).innerText, countText, rows };
  }));
  return raw.map((d) => {
    const t = clean(d.countText);
    const m = t.match(/^(\d+) ניטורים$/);
    return { day: clean(d.day), countText: t, rows: d.rows, count: t === 'ניטור אחד' ? 1 : m ? Number(m[1]) : null };
  });
}

// Ждём, пока у каждого заголовка дня есть число («ניטור אחד» / «N ניטורים») — без фиксированных пауз.
async function daysWithCounts(page: Page): Promise<Day[]> {
  let days: Day[] = [];
  await expect.poll(async () => {
    days = await readDays(page);
    return days.length > 0 && days.every((d) => d.count !== null);
  }, { message: 'у каждого заголовка дня есть число ניטורים' }).toBe(true);
  return days;
}

test.describe('История — число ניטורים в заголовке дня', () => {
  test('История: в заголовке каждого дня сразу полное число ניטורים, после «ניטורים קודמים» не меняется, после полной загрузки = числу записей дня #89b3e786 @iphone @prod-safe', async ({ page }) => {
    // 1. Открыть «היסטוריה», дождаться записей
    await page.goto('/history');
    const rows = page.getByRole('button', { name: ROW }).filter({ visible: true });
    await expect(rows.first(), 'сессия user.json недействительна — обновить из профиля devA').toBeVisible();

    // 2. Первая загрузка: число у каждого дня; не меньше уже показанных записей (у последнего дня — полное, а не загруженное)
    const seen = new Map<string, number>();
    for (const d of await daysWithCounts(page)) {
      expect(d.count!, `«${d.day}»: число не меньше показанных записей (${d.rows})`).toBeGreaterThanOrEqual(d.rows);
      seen.set(d.day, d.count!);
    }

    // 3. «ניטורים קודמים» до конца: число у уже показанных дней не меняется
    const more = page.getByRole('button', { name: 'ניטורים קודמים' }).filter({ visible: true });
    let pages = 0;
    while (await more.count()) {
      expect(++pages, 'не больше 20 догрузок').toBeLessThanOrEqual(20);
      const n = await rows.count();
      await more.scrollIntoViewIfNeeded();
      await more.click();
      await expect.poll(() => rows.count(), { message: 'догрузились новые записи' }).toBeGreaterThan(n);
      await expect(page.getByRole('progressbar').filter({ visible: true }), 'догрузка закончилась').toHaveCount(0);
      for (const d of await daysWithCounts(page)) {
        if (seen.has(d.day)) {
          expect(d.count, `«${d.day}»: число после «ניטורים קודמים» не изменилось («${d.countText}»)`).toBe(seen.get(d.day));
        } else {
          seen.set(d.day, d.count!);
        }
        expect(d.count!, `«${d.day}»: число не меньше показанных записей (${d.rows})`).toBeGreaterThanOrEqual(d.rows);
      }
    }

    // 4. Всё загружено: у каждого дня число = числу записей под ним; заголовки дней не повторяются
    const final = await daysWithCounts(page);
    expect(new Set(final.map((d) => d.day)).size, 'каждый день — одним заголовком').toBe(final.length);
    expect(final.reduce((s, d) => s + d.rows, 0), 'все записи стоят под заголовками дней').toBe(await rows.count());
    for (const d of final) {
      expect(d.count, `«${d.day}»: «${d.countText}» = ${d.rows} записей под заголовком`).toBe(d.rows);
    }
  });
});
